CREATE FUNCTION public.reader_preview_payload(p_id uuid,p_owner uuid,p_viewer uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path='' AS $$DECLARE s public.reader_shares;payload jsonb;BEGIN SELECT * INTO s FROM public.reader_shares WHERE id=p_id;IF NOT FOUND OR s.user_id<>p_owner OR NOT public.reader_preview_allows(s.user_id,s.visibility,s.club_id,p_viewer) THEN RETURN NULL;END IF;IF s.kind='book' THEN SELECT jsonb_build_object('title',title,'author',author) INTO payload FROM public.books WHERE id=s.source_id AND user_id=s.user_id;ELSIF s.kind='rating' THEN SELECT jsonb_build_object('title',title,'author',author,'stars',user_rating) INTO payload FROM public.books WHERE id=s.source_id AND user_id=s.user_id;ELSIF s.kind='list' THEN SELECT jsonb_build_object('title',name,'description',description,'items',(SELECT coalesce(jsonb_agg(jsonb_build_object('title',coalesce(b.title,w.title),'author',coalesce(b.author,w.author)) ORDER BY i.position,i.id),'[]'::jsonb) FROM public.reader_list_items i LEFT JOIN public.books b ON b.id=i.book_id AND b.user_id=s.user_id LEFT JOIN public.reader_wishes w ON w.id=i.wish_id AND w.user_id=s.user_id WHERE i.list_id=l.id AND i.user_id=s.user_id)) INTO payload FROM public.reader_lists l WHERE id=s.source_id AND user_id=s.user_id;ELSIF s.kind='bingo' THEN SELECT jsonb_build_object('title',title,'purpose',purpose,'size',size,'cells',cells,'source_credit',source_credit,'starts_on',starts_on,'ends_on',ends_on,'allow_reuse',allow_reuse) INTO payload FROM public.reader_bingos WHERE id=s.source_id AND user_id=s.user_id AND state='active';END IF;RETURN payload;END$$;
REVOKE ALL ON FUNCTION public.reader_preview_payload(uuid,uuid,uuid) FROM PUBLIC,authenticated,anon;
CREATE OR REPLACE FUNCTION public.reader_preview(p_mode text,p_handle text DEFAULT '',p_club uuid DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path='' AS $$DECLARE viewer uuid;profile public.reader_social_profiles;contents jsonb;BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Inicia sesión.';END IF;SELECT * INTO STRICT profile FROM public.reader_social_profiles WHERE user_id=auth.uid();IF p_mode='friend' THEN SELECT user_id INTO STRICT viewer FROM public.reader_social_profiles WHERE handle=lower(trim(leading '@' FROM p_handle));IF NOT EXISTS(SELECT 1 FROM public.reader_friendships WHERE state='accepted' AND ((requester=auth.uid() AND recipient=viewer) OR (recipient=auth.uid() AND requester=viewer))) THEN RAISE EXCEPTION 'Elige una amistad aceptada.';END IF;ELSIF p_mode='club' THEN SELECT user_id INTO STRICT viewer FROM public.reader_social_profiles WHERE handle=lower(trim(leading '@' FROM p_handle));IF viewer=auth.uid() OR NOT public.reader_club_member(p_club,auth.uid()) OR NOT public.reader_club_member(p_club,viewer) THEN RAISE EXCEPTION 'Elige otro integrante de tu club.';END IF;ELSIF p_mode<>'public' THEN RAISE EXCEPTION 'Vista inválida.';END IF;IF NOT public.reader_preview_allows(auth.uid(),profile.visibility,profile.club_id,viewer) THEN RETURN jsonb_build_object('profile',NULL,'contents','[]'::jsonb);END IF;SELECT coalesce(jsonb_agg(jsonb_build_object('kind',s.kind,'payload',public.reader_preview_payload(s.id,auth.uid(),viewer))) FILTER(WHERE public.reader_preview_allows(auth.uid(),s.visibility,s.club_id,viewer)),'[]'::jsonb) INTO contents FROM public.reader_shares s WHERE s.user_id=auth.uid();RETURN jsonb_build_object('profile',jsonb_build_object('handle',profile.handle,'name',profile.name,'bio',profile.bio),'contents',contents);END$$;
CREATE OR REPLACE FUNCTION public.reader_copy_bingo(p_share uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$DECLARE s public.reader_shares;b public.reader_bingos;result uuid;BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Inicia sesión.';END IF;SELECT * INTO STRICT s FROM public.reader_shares WHERE id=p_share FOR UPDATE;IF s.kind<>'bingo' OR NOT public.reader_can_view(s.user_id,s.visibility,s.club_id) THEN RAISE EXCEPTION 'No disponible.';END IF;SELECT id INTO result FROM public.reader_bingos WHERE user_id=auth.uid() AND shared_source_id=s.id;IF FOUND THEN RETURN result;END IF;SELECT * INTO STRICT b FROM public.reader_bingos WHERE id=s.source_id AND user_id=s.user_id AND state='active';INSERT INTO public.reader_bingos(user_id,title,purpose,size,cells,starts_on,ends_on,allow_reuse,shared_source_id,source_credit) VALUES(auth.uid(),b.title,b.purpose,b.size,b.cells,b.starts_on,b.ends_on,b.allow_reuse,s.id,b.source_credit) RETURNING id INTO result;UPDATE public.reader_bingos SET state='active' WHERE id=result;RETURN result;END$$;